def int_to_binary_string(n):
    if n == 0:
        return '0'
    bits = []
    x = n
    while x > 0:
        bits.append(str(x % 2))
        x //= 2
    return ''.join(reversed(bits))

def is_valid_simple_url(s):
    import re
    if ' ' in s:
        return False
    for prefix in ('http://', 'https://'):
        if s.startswith(prefix):
            rest = s[len(prefix):]
            break
    else:
        return False
    if not rest:
        return False
    path_start = rest.find('/')
    domain = rest if path_start == -1 else rest[:path_start]
    labels = domain.split('.') if domain else []
    if len(labels) < 2:
        return False
    label_re = re.compile(r'^[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?$')
    for lbl in labels:
        if not label_re.match(lbl):
            return False
    return labels[-1].isalpha() and len(labels[-1]) >= 2

def is_valid_sudoku_box(box):
