def mask_phone_all_but_last(digits, keep):
    n = len(digits)
    if keep <= 0:
        return '*' * n
    if keep >= n:
        return digits
    masked_len = n - keep
    return '*' * masked_len + digits[n - keep:]

def mask_phone_middle(digits):
    if len(digits) <= 5:
        return '*' * len(digits)
    middle = len(digits) - 5
    return digits[:3] + '*' * middle + digits[-2:]

