def normalize_ranks_dense(scores):
    distinct = sorted(set(scores))
    count = len(distinct)
    if count <= 1:
        return [0.0 for _ in scores]
    rank_of = {}
    for i, val in enumerate(distinct):
        rank_of[val] = i
    output = []
    for s in scores:
        output.append(round(rank_of[s] / (count - 1), 4))
    return output

