def add_months_to_date(y, m, d, n_months):
    def is_leap(year):
        return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
    total_months = (y * 12 + (m - 1)) + n_months
    new_year = total_months // 12
    new_month = total_months % 12 + 1
    days_table = [31, 29 if is_leap(new_year) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    max_day = days_table[new_month - 1]
    new_day = d if d <= max_day else max_day
    return (new_year, new_month, new_day)

